    public class SubscriptionController : Controller
    {
        private StripeSettings _stripeSettings;

        public SubscriptionController(StripeSettings stripeSettings)
        {
            _stripeSettings = stripeSettings;
        }

        [HttpPost]
        public ActionResult CreateSubscription(string customerId, int planId, string trialAmount)
        {
            try
            {
                // Create a new subscription
                var subscriptionService = new SubscriptionService(_stripeSettings.SecretKey);
                var subscription = new SubscriptionCreateOptions
                {
                    Customer = customerId,
                    Items = new List<SubscriptionItemOptions>
                    {
                        new SubscriptionItemOptions
                        {
                            Plan = planId.ToString(),
                            Quantity = 1,
                        }
                    },
                    TrialPeriodDays = 30, // trial period in days
                    TrialAmount = decimal.Parse(trialAmount), // trial amount in cents
                };

                var subscriptionResponse = subscriptionService.Create(subscription);

                if (subscriptionResponse.Status == "succeeded")
                {
                    // Subscription created successfully
                    TempData["SubscriptionId"] = subscriptionResponse.Id;
                    return RedirectToAction("Success");
                }
                else
                {
                    // Error creating subscription
                    TempData["Error"] = subscriptionResponse.StatusCode;
                    return RedirectToAction("Error");
                }
            }
            catch (StripeException ex)
            {
                // Stripe exception occurred
                TempData["Error"] = ex.Message;
                return RedirectToAction("Error");
            }
        }

        public ActionResult Success()
        {
            // Redirect to a success page or perform additional actions
            return View();
        }

        public ActionResult Error()
        {
            // Redirect to an error page or perform additional actions
            return View();
        }
    }
}
