  double term2 = 3.0 * pow(1 + h / (zeta * alpha), 4) - 4.0 * pow(1 + h / (zeta * alpha), 2) + 1;
  double term3 = -4.0 * pow(1 + h / (zeta * alpha), 4) * log(1 + h / (zeta * alpha));
  return term1 * term2 + term3;
}

