  double term2 = 1.0 - alpha * dhz / (zetaAlpha + h);
  double term3 = (1 + pow(dhz, 2)) ^ (3.0 / 2.0);
  return -gamma * (term1 / term3 - term2 / (zetaAlpha + h) / term3 ^ (1.0 / 2.0));
}

void solve() {
