```
// Estructura para representar un nodo en el árbol binario
struct Node {
    int valor;
    Node* left;
    Node* right;
};

// Clase para implementar la búsqueda en el árbol binario
class BinarySearchTree {
public:
    // Constructor para crear un árbol vacío
    BinarySearchTree() : root(nullptr) {}

    // Método para insertar un nuevo nodo en el árbol
    void insert(int valor) {
        root = insertRecursive(root, valor);
    }

    // Método para buscar un valor en el árbol
    bool buscar(int valor) {
        return buscarRecursive(root, valor);
    }

private:
    // Nodo raíz del árbol
    Node* root;

    // Metodología recursiva para insertar un nuevo nodo en el árbol
    Node* insertRecursive(Node* node, int valor) {
        if (node == nullptr) {
            node = new Node();
            node->valor = valor;
            node->left = nullptr;
            node->right = nullptr;
        } else if (valor < node->valor) {
            node->left = insertRecursive(node->left, valor);
        } else if (valor > node->valor) {
            node->right = insertRecursive(node->right, valor);
        }
        return node;
    }

    // Metodología recursiva para buscar un valor en el árbol
    bool buscarRecursive(Node* node, int valor) {
        if (node == nullptr) {
            return false;
        } else if (valor == node->valor) {
            return true;
        } else if (valor < node->valor) {
            return buscarRecursive(node->left, valor);
        } else {
            return buscarRecursive(node->right, valor);
        }
    }
};
```
