import { GoogleAuth } from 'react-google-login';
import { MuiButton } from '@material-ui/core';

class SessionManager extends Component {
  constructor(props) {
    super(props);
    this.state = {
      isLoggedIn: false,
      accessToken: '',
      expirationTime: 0,
    };
  }

  handleGoogleLogin = (response) => {
    const { accessToken, expirationTime } = response;
    this.setState({
      isLoggedIn: true,
      accessToken,
      expirationTime,
    });
  };

  handleGoogleLogout = () => {
    this.setState({
      isLoggedIn: false,
      accessToken: '',
      expirationTime: 0,
    });
  };

  render() {
    const { isLoggedIn, accessToken } = this.state;
    return (
      <div>
        {isLoggedIn ? (
          <div>
            <h2>Welcome, {this.props.user.name}</h2>
            <MuiButton
              variant="contained"
              color="primary"
              onClick={this.handleGoogleLogout}
            >
              Logout
            </MuiButton>
          </div>
        ) : (
          <div>
            <h2>Login with Google</h2>
            <GoogleAuth
              clientId="YOUR_CLIENT_ID"
              buttonText="Login with Google"
              onSuccess={this.handleGoogleLogin}
              onFailure={this.handleGoogleLogin}
            />
          </div>
        )}
      </div>
    );
  }
}

export default SessionManager;
```

