Here's an example code snippet in Delphi 7 that uses PDFlib to rotate a PDF file:
```delphi
program RotatePDF;

uses
  PDFlibResponseType,
  PDFlibFunctions,

  System.Classes,
  System.SysUtils;

var
  pdf: TPDFlib;
  filename: string;
  rotation: Integer;

begin
  // Initialize PDFlib
  pdf := TPFDlib.Create(nil);

  // Set the input file
  filename := 'input.pdf';

  // Rotate the PDF by 90 degrees clockwise
  rotation := 90;

  // Load the PDF file
  pdf.LoadFile(filename);

  // Rotate the PDF
  pdf.RotatePage(-1, rotation);

  // Save the rotated PDF file
  pdf.SaveFile('output.pdf');

  // Clean up
  pdf.Free;
end.
```
